const HUGGINGFACE_MAX_RETRIES: usize = 5;
const HUGGINGFACE_RETRY_DELAY: Duration = Duration::from_secs(2);

// ── Types ──────────────────────────────────────────────────────────────────────

/// Arguments for saving a handwriting image attachment.
#[derive(Deserialize)]
pub struct SaveHandwritingAttachmentArgs {
