                .map(|path| path.exists())
                .unwrap_or(false),
            model_path: model_path.to_string_lossy().into_owned(),
            error: None,
        };
    }

    let result = ensure_local_ocr_env(app).and_then(|python| {
        fs::create_dir_all(model_path).map_err(|error| error.to_string())?;
        let output = run_script(
            &python,
